</div>

<script>

    localStorage.removeItem('ankiUserSpeechInput');
    let recognition;

    document.addEventListener('DOMContentLoaded', function () {
        const button = document.getElementById('floatingButton');
        const savedPosition = JSON.parse(localStorage.getItem('buttonPosition'));
        if (savedPosition) {
            button.style.left = savedPosition.left;
            button.style.top = savedPosition.top;
        }
        makeDraggable(button);
        setTimeout(startSpeechRecognition, 400);
        button.addEventListener('click', function () {
            if (recognition) { try { recognition.abort(); } catch (e) {} }
            startSpeechRecognition();
        });
