    function startSpeechRecognition() {
        if (!('SpeechRecognition' in window || 'webkitSpeechRecognition' in window)) {
            alert("Reconhecimento de voz não suportado.");
            return;
        }
        recognition = new (window.SpeechRecognition || window.webkitSpeechRecognition)();
        recognition.lang = 'pt-BR';

        recognition.onresult = (event) => {
            const spokenText = event.results[0][0].transcript;


            localStorage.setItem('ankiUserSpeechInput', spokenText);

            document.getElementById('recognized-text').textContent = spokenText;
            document.getElementById('result-container').style.display = 'block';
            showAnswer();
        };

        recognition.onerror = (event) => {
            if (event.error !== 'no-speech') {
                document.getElementById('recognized-text').textContent = `Erro: ${event.error}`;
                document.getElementById('result-container').style.display = 'block';
            }
        };

        recognition.onstart = () => { document.getElementById('floatingButton').textContent = "Ouvindo..."; };
        recognition.onend = () => { document.getElementById('floatingButton').textContent = "🎤 Ditar"; };
        recognition.start();
    }

    function makeDraggable(element) {
        let offsetX, offsetY, isDragging = false;
        function startDrag(e) {
            isDragging = true;
            const rect = element.getBoundingClientRect();
            offsetX = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
            offsetY = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
            document.addEventListener('touchmove', dragMove, { passive: false });
            document.addEventListener('touchend', endDrag, false);
        }
        function dragMove(e) {
            if (!isDragging) return;
            e.preventDefault();
            const x = (e.touches ? e.touches[0].clientX : e.clientX) - offsetX;
            const y = (e.touches ? e.touches[0].clientY : e.clientY) - offsetY;
            element.style.left = x + 'px';
            element.style.top = y + 'px';
        }
        function endDrag() {
            if (!isDragging) return;
            isDragging = false;
            localStorage.setItem('buttonPosition', JSON.stringify({ left: element.style.left, top: element.style.top }));
            document.removeEventListener('touchmove', dragMove);
            document.removeEventListener('touchend', endDrag, false);
        }
        element.addEventListener('touchstart', startDrag, { passive: false });
    }
</script>

